export const KEY_PREFIX="lateen-feedback:";export function keyFor(url){return`${KEY_PREFIX}${url}`;}
export function read(storage,url){try{const saved=storage.getItem(keyFor(url));return saved==="yes"||saved==="no"?saved:undefined;}catch{return undefined;}}
export function save(storage,url,vote){try{storage.setItem(keyFor(url),vote);}catch{}}
export function voteOf(button){return button.dataset.vote==="yes"||button.dataset.vote==="no"?button.dataset.vote:undefined;}
export function submit(endpoint,payload,post){return post(endpoint,JSON.stringify(payload));}
export function finish(root,text){for(const button of root.querySelectorAll("[data-feedback-vote]")){button.hidden=true;button.disabled=true;}
const status=root.querySelector(".feedback-status");if(status!==null)status.textContent=text;}
export function vote(root,button,env){const answer=voteOf(button);const endpoint=root.dataset.endpoint??"";const url=root.dataset.url??"";if(answer===undefined||endpoint===""||url==="")return Promise.resolve();for(const other of root.querySelectorAll("[data-feedback-vote]"))other.disabled=true;return submit(endpoint,{url,helpful:answer==="yes"},env.post).then(()=>{save(env.storage,url,answer);finish(root,root.dataset.thanks??"");},()=>{finish(root,root.dataset.failed??"");},);}
export function activate(root,env){const endpoint=root.dataset.endpoint??"";const url=root.dataset.url??"";if(endpoint===""||url==="")return;root.hidden=false;if(read(env.storage,url)!==undefined){finish(root,root.dataset.already??"");return;}
const buttons=[...root.querySelectorAll("[data-feedback-vote]")];if(buttons.length===0)return;for(const button of buttons){button.hidden=false;button.addEventListener("click",()=>{void vote(root,button,env);});}}
const globals=globalThis;function browserPost(endpoint,body){const fetch=globals.fetch;if(fetch===undefined)return Promise.reject(new Error("fetch is unavailable"));return fetch(endpoint,{method:"POST",headers:{"content-type":"application/json"},body,}).then((response)=>{if(!response.ok)throw new Error(`HTTP ${response.status}`);});}
if(globals.document!==undefined){const root=globals.document.querySelector("[data-feedback]");if(root!==null&&globals.sessionStorage!==undefined&&globals.fetch!==undefined){activate(root,{storage:globals.sessionStorage,post:browserPost});}}